// FUNCTION: BFME2 0x0053F53C size=257 name=?update@WindowVideoManager@@UAEXXZ evidence=N:ledger
void WindowVideoManager::update()
{
	WindowVideoMap::iterator cursor = m_playingVideos.begin();
	if (m_pauseAllMovies || m_stopAllMovies)
		return;
	while (cursor != m_playingVideos.end())
	{
		WindowVideo *video = cursor->second;
		if (video == 0)
			return;
		GameWindow *win = video->m_win;
		if (video->m_state == WINDOW_VIDEO_STATE_HIDE)
		{
			if (!win->winIsHidden())
				resumeMovie(win);
		}
		if (video->m_state == WINDOW_VIDEO_STATE_PLAY)
		{
			if (win->winIsHidden())
				hideMovie(win);
		}
		if (video->m_state != WINDOW_VIDEO_STATE_PLAY)
		{
			cursor++;
			continue;
		}
		VideoStreamInterface *stream = video->m_videoStream;
		VideoBuffer *buffer = video->getVideoBuffer();
		if (stream != 0 && buffer != 0)
		{
			switch (video->m_playType)
			{
			case WINDOW_PLAY_MOVIE_LOOP:
				stream->update(4);
				break;
			case WINDOW_PLAY_MOVIE_SHOW_LAST_FRAME:
				if ((stream->update(0) & 1) && stream->frameIndex() == 0)
					pauseMovie(win);
				break;
			default:
				if ((stream->update(0) & 1) && stream->frameIndex() == 0)
					stopMovie(win);
				break;
			}
		}
		cursor++;
	}
}

// FUNCTION: BFME2 0x0053F63D size=228 name=?playMovie@WindowVideoManager@@QAEXPAVGameWindow@@VAsciiString@@W4WindowVideoPlayType@@@Z evidence=N:ledger
void WindowVideoManager::playMovie(GameWindow *win, AsciiString movieName, WindowVideoPlayType playType)
{
	WindowVideo *video = 0;
	stopAndRemoveMovie(win);
	VideoStreamInterface *stream = TheVideoPlayer->open(movieName, 0);
	if (stream == 0)
		return;
	if (!stream->setVideoBuffer(TheDisplay->createVideoBuffer(false)))
	{
		stream->close();
		return;
	}
	video = new WindowVideo;
	video->init(win, movieName, playType, stream);
	m_playingVideos[win] = video;
	m_pauseAllMovies = false;
	m_stopAllMovies = false;
}

